  "implementation": "def solve(case):
    passing = case['passing']
    failing = case['failing']
    required = set(case['required_difference'])
    unresolved = set(case['unresolved_difference'])

    # full difference in order they appear in failing
    pass_set = set(passing)
    full_diff = [x for x in failing if x not in pass_set]

    test_count = 0

    def test(subset):
        nonlocal test_count
        test_count += 1
        subset_set = set(subset)
        if required.issubset(subset_set):
            return 'FAIL'
        if subset_set & unresolved:
            return 'UNRESOLVED'
        return 'PASS'

    def ddmin(s):
        nonlocal test_count
        # initial test of the current set (should be FAIL)
        outcome = test(s)
        if outcome != 'FAIL':
            # should not happen for a failing set, but guard
            return s[:]
        if len(s) == 1:
            return s[:]

        n = 2
        while n <= len(s):
            # partition into n contiguous subsets
            part_len = len(s) // n
            subsets = []
            for i in range(n):
                start = i * part_len
                end = (i+1)*part_len if i < n-1 else len(s)
                subsets.append(s[start:end])

            for subset in subsets:
                out = test(subset)
                if out == 'FAIL':
                    return ddmin(subset)
                # complement of this subset (preserves order)
                complement = [x for x in s if x not in subset]
                out_comp = test(complement)
                if out_comp == 'FAIL':
                    return ddmin(complement)
            n += 1

        # no reduction possible
        return s[:]

    isolated = ddmin(full_diff)
    return {
        'isolated_difference': isolated,
        'tests': test_count
    }
